  // big tent right
  ctx.fillStyle = "#b35a3b";
  ctx.beginPath();
  ctx.moveTo(cx + 9 * s, cy + 10 * s);
  ctx.lineTo(cx + 29 * s, cy - 37 * s);
  ctx.lineTo(cx + 49 * s, cy + 6 * s);
