    top: "#a9b5b4",
    left: "#68777a",
    right: "#859291",
  });
  // block lines
  ctx.strokeStyle = "rgba(56,71,76,.4)";
  ctx.lineWidth = 0.8 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 27 * s, cy - 9 * s);
  ctx.lineTo(cx, cy + 5 * s);
  ctx.lineTo(cx + 27 * s, cy - 9 * s);
