+function generateOpponents() {
+  const level = G.state.profile.level;
+  const rand = seededRandom(now() % 2147483647);
+  const names = [...OPPONENT_NAMES].sort(() => rand() - 0.5);
+  return Array.from({ length: 3 }, (_, i) => {
